```verilog
module cdc_fifo_gray #(
    parameter WIDTH = 8,
    parameter LOG_DEPTH = 3,
    parameter SYNC_STAGES = 2
)(
    input                  src_rst_ni,
    input                  src_clk_i,
    input  [WIDTH-1:0]     src_data_i,
    input                  src_valid_i,
    output                 src_ready_o,
    input                  dst_rst_ni,
    input                  dst_clk_i,
    output [WIDTH-1:0]     dst_data_o,
    output                 dst_valid_o,
    input                  dst_ready_i
);

    localparam FIFO_DEPTH = 1 << LOG_DEPTH;

    // Internal signals
    logic [LOG_DEPTH:0] src_wr_ptr;
    logic [LOG_DEPTH:0] dst_rd_ptr;
    logic [LOG_DEPTH:0] wr_ptr_sync;
    logic [LOG_DEPTH:0] rd_ptr_sync;
    logic [WIDTH-1:0] fifo [0:FIFO_DEPTH-1];
    logic full;
    logic empty;

    // Synchronizers for src_clk_i domain
    logic [SYNC_STAGES:0] src_wr_ptr_sync_stages [0:SYNC_STAGES];
    logic [SYNC_STAGES:0] src_rd_ptr_sync_stages [0:SYNC_STAGES];

    // Synchronizers for dst_clk_i domain
    logic [SYNC_STAGES:0] dst_wr_ptr_sync_stages [0:SYNC_STAGES];
    logic [SYNC_STAGES:0] dst_rd_ptr_sync_stages [0:SYNC_STAGES];

    // Source clock domain logic
    always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
        if (!src_rst_ni) begin
            src_wr_ptr <= 0;
        end else begin
            if (src_valid_i && src_ready_o && !full) begin
                src_wr_ptr <= src_wr_ptr + 1;
            end
        end
    end

    // Destination clock domain logic
    always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
        if (!dst_rst_ni) begin
            dst_rd_ptr <= 0;
        end else begin
            if (dst_ready_i && dst_valid_o && !empty) begin
                dst_rd_ptr <= dst_rd_ptr + 1;
            end
        end
    end

    // Full and empty flags
    assign full = (src_wr_ptr == dst_rd_ptr) & src_valid_i;
    assign empty = (src_wr_ptr == dst_rd_ptr) & ~src_valid_i;

    // Synchronizers for src_clk_i domain
    always_ff @(posedge src_clk_i) begin
        src_wr_ptr_sync_stages[0] <= src_wr_ptr;
        for (int i = 1; i <= SYNC_STAGES; i++) begin
            src_wr_ptr_sync_stages[i] <= src_wr_ptr_sync_stages[i-1];
        end
    end

    always_ff @(posedge src_clk_i) begin
        src_rd_ptr_sync_stages[0] <= src_rd_ptr;
        for (int i = 1; i <= SYNC_STAGES; i++) begin
            src_rd_ptr_sync_stages[i] <= src_rd_ptr_sync_stages[i-1];
        end
    end

    assign wr_ptr_sync = src_wr_ptr_sync_stages[SYNC_STAGES];

    // Synchronizers for dst_clk_i domain
    always_ff @(posedge dst_clk_i) begin
        dst_wr_ptr_sync_stages[0] <= dst_wr_ptr;
        for (int i = 1; i <= SYNC_STAGES; i++) begin
            dst_wr_ptr_sync_stages[i] <= dst_wr_ptr_sync_stages[i-1];
        end
    end

    always_ff @(posedge dst_clk_i) begin
        dst_rd_ptr_sync_stages[0] <= dst_rd_ptr;
        for (int i = 1; i <= SYNC_STAGES; i++) begin
            dst_rd_ptr_sync_stages[i] <= dst_rd_ptr_sync_stages[i-1];
        end
    end

    assign rd_ptr_sync = dst_rd_ptr_sync_stages[SYNC_STAGES];

    // Output logic
    assign src_ready_o = ~full;
    assign dst_data_o = fifo[rd_ptr_sync];
    assign dst_valid_o = ~empty;

    // FIFO memory
    generate
        generate
            generate
                generate
